<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ApiError, get, post, session } from '../api'
import RiskTag from '../components/RiskTag.vue'
const route=useRoute(), p=ref<any>(), quick=ref(false), saving=ref(false), error=ref(''), note=ref('')
const labels:Record<string,string>={BIDDING:'招标代理',COST:'造价/预结算',SUPERVISION:'监理',OTHER:'其他'}
const next=computed(()=>p.value?.milestones.filter((m:any)=>!m.actualDate).sort((a:any,b:any)=>String(a.plannedDate).localeCompare(String(b.plannedDate)))[0])
const money=(n:number)=>`¥${Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:2})}`
async function load(){error.value='';try{p.value=await get(`/projects/${route.params.id}`)}catch(e){error.value=e instanceof ApiError?e.message:'项目加载失败'}}
async function quickSave(){if(!p.value)return;saving.value=true;try{await post(`/projects/${p.value.id}/quick-update`,{status:p.value.status,note:note.value});quick.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
onMounted(load)
</script>
<template><div v-if="!p&&!error" class="empty"><p>正在加载项目…</p></div><div v-else-if="error" class="empty"><h3>无法打开项目</h3><p class="error">{{error}}</p><RouterLink to="/projects" class="button secondary">返回项目列表</RouterLink></div><template v-else-if="p"><div class="eyebrow">{{p.status==='ACTIVE'?'在办':p.status==='COMPLETED'?'已完成':'已取消'}} · {{p.services.map((s:any)=>labels[s.serviceType]).join(' / ')}}</div><div class="detail-hero"><div><h1 class="title" style="margin-top:10px">{{p.name}}</h1><p class="subtitle">{{p.client?.name}} · {{p.owner?.name}}</p><div style="margin-top:16px"><RiskTag v-for="r in p.risks" :key="r.reason" :level="r.level" :text="r.reason"/></div></div><div v-if="!session.isDemo" class="actions" style="margin:0"><RouterLink :to="`/projects/${p.id}/edit`" class="button secondary">编辑项目</RouterLink><button class="button primary" @click="quick=true">快速更新</button></div></div><div class="hero-metrics"><div class="metric"><label>下一关键节点</label><strong>{{next?.name||'暂无'}}</strong><small class="subtitle" style="display:block;margin-top:8px">{{next?.plannedDate||'可在后续版本补充节点'}}</small></div><div class="metric"><label>当前应收</label><strong>{{money(p.finance.receivableAmount)}}</strong><small class="subtitle" style="display:block;margin-top:8px">已回款 {{money(p.finance.paymentAmount)}}</small></div></div><div class="detail-grid"><section><h2 class="section-title">服务</h2><div class="list"><div v-for="s in p.services" :key="s.id" class="list-row"><b>{{labels[s.serviceType]}}</b><span>{{s.stage}}</span><span class="subtitle">{{s.otherDescription||s.note}}</span></div></div><h2 class="section-title" style="margin-top:32px">时间</h2><div class="list"><div v-for="m in p.milestones" :key="m.id" class="list-row"><span class="eyebrow">{{m.plannedDate}}</span><span>{{m.name}}</span><RiskTag v-if="!m.actualDate&&m.plannedDate<new Date().toISOString().slice(0,10)" level="danger" text="延期"/><span v-else class="subtitle">{{m.actualDate?'已完成':'待完成'}}</span></div><p v-if="!p.milestones.length" class="subtitle">暂无节点。</p></div></section><aside><h2 class="section-title">经营</h2><div class="list"><div v-for="row in [['合同额',p.finance.contractAmount],['已开票',p.finance.invoiceAmount],['已回款',p.finance.paymentAmount],['应收',p.finance.receivableAmount]]" :key="row[0]" class="list-row"><span>{{row[0]}}</span><b>{{money(Number(row[1]))}}</b></div></div><h2 class="section-title" style="margin-top:32px">文件 {{p.documents.length}}</h2><p v-if="!p.documents.length" class="subtitle">暂无文件。</p><div v-else class="list"><div v-for="d in p.documents" :key="d.id" class="list-row"><span>{{d.originalName}}</span><span class="subtitle">{{d.title}}</span></div></div></aside></div><el-dialog v-if="!session.isDemo" v-model="quick" title="快速更新" width="min(540px,92vw)"><div class="field-group"><label>项目状态</label><select v-model="p.status" class="select"><option value="ACTIVE">在办</option><option value="COMPLETED">已完成</option><option value="CANCELLED">已取消</option></select></div><div class="field-group" style="margin-top:15px"><label>管理备注</label><textarea v-model="note" class="textarea" rows="3"/></div><template #footer><button class="button secondary" @click="quick=false">取消</button><button class="button primary" :disabled="saving" @click="quickSave">{{saving?'保存中…':'保存更新'}}</button></template></el-dialog></template></template>
